function setBits(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || /[^01]/.test(a) || /[^01]/.test(b) || a.length !== b.length) throw new TypeError("Matching bit strings required");
  const out = {union: "", intersection: "", difference: "", complement: "", symmetric: ""};
  for (let i = 0; i < a.length; i++) {
    const p = a[i] === "1", q = b[i] === "1";
    const bits = [p || q, p && q, p && !q, !p, p !== q];
    ["union", "intersection", "difference", "complement", "symmetric"].forEach((key, j) => { out[key] += bits[j] ? "1" : "0"; });
  }
  return out;
}
